import{z as i,x as o,o as A,c as s,q as B,j as l,D as a,d as t,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"对齐数据工程收束","description":"","frontmatter":{"title":"对齐数据工程收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-map.md","filePath":"llm/ade-map.md","lastUpdated":1791413859000}'),p={name:"llm/ade-map.md"};function D(d,E,C,m,F,_){const e=o("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="对齐数据工程收束" tabindex="-1">对齐数据工程收束 <a class="header-anchor" href="#对齐数据工程收束" aria-label="Permalink to &quot;对齐数据工程收束&quot;">​</a></h1><div class="epigraph"><p>对齐数据工程是把价值观写成可版本化的数据资产：原则与指南是锚，边界对是内容，配比是工作点，仪表是闭环。</p><footer>—— 据 Ouyang 等 InstructGPT 2022、Bai 等 Constitutional AI 2022、Touvron 等 Llama 2 2023，按本课程整理</footer></div><p><a href="/llm/ade-eval-loop">上一课</a>把数据仪表接上模型评测的门禁，归因三分让每个失败有了对应的动作，闭环成形。本课程从 <a href="/llm/rm-engineering-map">RM 工程收束</a>的「数据定天花板」开卷，经数据构建与质量配比两单元九课，至此收束。收束课做该做的事：把两个单元放回同一张账，写明每课回答的问题、留下的手段，以及它们共享的那条主线。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把九课压成一个判断：对齐数据工程管两件事。构建单元管把「好」的定义写成数据——生命周期给资产观（版本、账本、退役），提示覆盖给管辖范围（意图分类法与格子配额），红队沉淀给边界（训练对、对照对、评训分离），constitutional 生产给可编程性（原则集直接编程分布）。质量与配比单元管守住定义的执行——去重清洗守住单条质量与簇密度（清洗即再配比），配比守住工作点（分域下限、帕累托读数），轮次策略守住时间轴（贬值、锚漂移、混锚），评测闭环守住归因（没覆盖、标错、版本过期三分）。缺任何一件的失效形态，都在各自的课里见过：定义失版本，行为漂移无账可查；覆盖失格子，边界留外推的洞；沉淀失对照，越权拒绝疯长；闭环失归因，预算全花在盲目的补采上。</p><p><span class="marginnote">「经验分布」翻译过来就是「你实际采到的数据长什么样」。模型学到的不是抽象的「好」，而是数据里那些好坏对比的统计规律。所以「根本解是改数据的经验分布」意思是：想改变模型，最直接的办法不是改损失函数，而是改变它见过的例子。</span></p>',6)),(A(),l(n,null,{default:a(()=>[r(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20U1%5B%22%E6%95%B0%E6%8D%AE%E6%9E%84%E5%BB%BA%EF%BC%9A%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%20%2F%20%E8%A6%86%E7%9B%96%20%2F%20%E7%BA%A2%E9%98%9F%20%2F%20constitutional%22%5D%20--%3E%20ASSET%5B%22%E6%95%B0%E6%8D%AE%E8%B5%84%E4%BA%A7%EF%BC%9A%E5%B8%A6%E5%9B%9B%E5%85%83%E7%BB%84%E7%89%88%E6%9C%AC%E7%9A%84%E6%95%B0%E6%8D%AE%E5%8D%A1%22%5D%0A%20%20U2%5B%22%E8%B4%A8%E9%87%8F%E4%B8%8E%E9%85%8D%E6%AF%94%EF%BC%9A%E6%B8%85%E6%B4%97%20%2F%20%E9%85%8D%E6%AF%94%20%2F%20%E8%BD%AE%E6%AC%A1%20%2F%20%E9%97%AD%E7%8E%AF%22%5D%20--%3E%20ASSET%0A%20%20ASSET%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20MODEL%20--%3E%20GATE%5B%22%E8%AF%84%E6%B5%8B%E9%97%A8%E7%A6%81%22%5D%0A%20%20GATE%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%E5%BD%92%E5%9B%A0%E4%B8%89%E5%88%86%22%7C%20U2%0A%20%20GATE%20--%3E%7C%22%E6%94%BF%E7%AD%96%E6%94%B9%E7%89%88%22%7C%20U1%0A%20%20MODEL%20--%3E%7C%22%E7%AD%96%E7%95%A5%E7%A7%BB%E5%8A%A8%EF%BC%8C%E6%95%B0%E6%8D%AE%E8%B4%AC%E5%80%BC%22%7C%20U2%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每课留下一件可持续的东西。生命周期留下资产观与四元组版本；覆盖留下分类法与格子配额；红队沉淀留下「评训分离加对照对」；constitutional 留下「改原则即改分布」的产线；清洗留下丢弃记账；配比留下分域下限与工作点；轮次留下「提示是资产、比较对是耗材」的分层账本；闭环留下三分归因与三条上线断言。每件都能独立运行，合起来是一份新项目的开工顺序：先钉政策与指南的版本号，再立分类法与数据卡，然后才是采集与规模。顺序反了的项目，会在第三轮迭代时找不到「第零轮的边界是什么」。</p><p><span class="marginnote">「先钉版本号再采集」听起来像官僚流程，其实省的是最贵的钱：若到第三轮才发现第零轮的边界没记录在案，唯一的办法是把前三轮数据全部重标——重标的价钱通常是当初标注的两三倍，还不算三轮训练全部白跑。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>全课程的主线只有一条，而且与<a href="/llm/rm-engineering-map">奖励模型工程</a>的主线是同一条的两段：指南与原则写下的每一个锚，经偏好对进入 BT 损失，变成 RM 的判别边界；策略再把这个边界放大成行为。「好」的定义在文本里写下多清楚，边界就立得多稳；定义的版本管理多松，行为就漂得多远。课程里所有根本解都作用在同一环——改数据的经验分布：对照对在边界另一侧加样本，格子配额在欠覆盖处加样本，原则改写直接改分布的定义，重标把锚的版本对齐。凡是绕开这一环、在损失端或评测端做局部止血的，都有副作用，只配当第二道防线。</p><p>这条主线上的每一环如何接力、根本解插在哪一环，画出来是一张接力图：</p>',6)),(A(),l(n,null,{default:a(()=>[r(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%8E%9F%E5%88%99%E4%B8%8E%E6%8C%87%E5%8D%97%EF%BC%9A%E5%86%99%E4%B8%8B%E3%80%8C%E5%A5%BD%E3%80%8D%E7%9A%84%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20B%5B%22%E5%81%8F%E5%A5%BD%E5%AF%B9%EF%BC%9A%E5%AE%9A%E4%B9%89%E8%90%BD%E6%88%90%E5%85%B7%E4%BD%93%E4%BE%8B%E5%AD%90%22%5D%0A%20%20B%20--%3E%20C%5B%22BT%20%E6%8D%9F%E5%A4%B1%EF%BC%9A%E5%AF%B9%E6%AF%94%E5%8F%98%E6%88%90%E8%AE%AD%E7%BB%83%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20C%20--%3E%20D%5B%22RM%20%E5%88%A4%E5%88%AB%E8%BE%B9%E7%95%8C%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%AD%96%E7%95%A5%E5%AD%A6%E4%B9%A0%EF%BC%9A%E8%BE%B9%E7%95%8C%E6%94%BE%E5%A4%A7%E6%88%90%E8%A1%8C%E4%B8%BA%22%5D%0A%20%20A%20--%3E%7C%22%E7%89%88%E6%9C%AC%E7%AE%A1%E7%90%86%E6%9D%BE%22%7C%20DRIFT%5B%22%E8%A1%8C%E4%B8%BA%E6%BC%82%E7%A7%BB%22%5D%0A%20%20FIX%5B%22%E6%A0%B9%E6%9C%AC%E8%A7%A3%EF%BC%9A%E6%94%B9%E6%95%B0%E6%8D%AE%E7%9A%84%E7%BB%8F%E9%AA%8C%E5%88%86%E5%B8%83%22%5D%20--%3E%20B%0A%20%20BAND%5B%22%E6%8D%9F%E5%A4%B1%E7%AB%AF%20%2F%20%E8%AF%84%E6%B5%8B%E7%AB%AF%E6%AD%A2%E8%A1%80%22%5D%20-.-%3E%7C%22%E7%AC%AC%E4%BA%8C%E9%81%93%E9%98%B2%E7%BA%BF%22%7C%20D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">给新项目的自查顺序：先问「好」的定义写在哪份文档、第几版；再问每格数据的判断锚是谁、一致率多少；最后才问模型多大、损失怎么选。顺序反了，预算通常会从第一问流到第三问。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束即边界。本课程全部方法以「好可成文、边界可由对比表达」为前提；判断超出成文范围的问题站在<a href="/llm/scalable-oversight">可扩展监督</a>的地界，偏好由强裁判代打的部分继承了裁判的偏差（<a href="/llm/generative-rm">生成式奖励模型</a>是那边的入口）。可验证域是另一个出口：验证器不需要一致率，本课程大半仪表在那里用不上，工程量换成了「验证器覆盖不到什么」的新问题（<a href="/llm/rlvr-design-space">RLVR 的设计空间</a>）。最后，对齐数据工程的输出从不只是训练数据：它把一个组织的价值观写成原则集、指南、数据卡与仪表——这四样东西比任何单个模型活得都久。</p><p><span class="marginnote">「可验证域」指答案能被程序自动判对错的问题：代码能不能跑通、数学题答案对不对。这类问题不需要人标偏好，自然也用不上一致率仪表；但「回答有没有礼貌」「建议是否稳妥」这类没有验证器的问题，仍要走本课程的人标路线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全课主线：定义写成锚，锚经数据变成边界，策略把边界放大成行为；定义的版本管理决定行为漂移。</li><li>构建单元四件：资产观与版本、覆盖矩阵、评训分离的沉淀、原则可编程的产线。</li><li>质量与配比单元四件：清洗记账、分域下限与工作点、轮次分层账本、三分归因闭环。</li><li>根本解都在改数据的经验分布；损失端与评测端是第二道防线。</li><li>出处：Ouyang 等 InstructGPT，2022；Bai 等 Constitutional AI，2022；Touvron 等 Llama 2，2023；Ganguli et al., 2022，按本课程整理。</li></ul>',6))])}const T=i(p,[["render",D]]);export{u as __pageData,T as default};
